SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ TABLE01.BRANCH branch,/*分支序号*/ NVL(TABLE02.AMOUNT,0) * 100 posStrdPrinAmt,/*持仓券面总额*/ NVL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt,/*可质押券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ ETR_ENTRUST_PLEDGE.SCALE scale, /*折算比例*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ FIN_PRODUCT.REGIST_ORG registOrg,/*登记托管机构*/ NVL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) finProdName,/*金融产品名称*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId/*市场代码*/ FROM ETR_ENTRUST_PLEDGE LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，05融入，06融出,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 /*以上统计实际持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE02.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE02.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{plateDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = (CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID /*以上获取债券小于等于平台日的最新估值行情*/ WHERE 1=1 /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND (ETR_ENTRUST_PLEDGE.PORTFOLIO_ID in
null) or ETR_ENTRUST_PLEDGE.PORTFOLIO_ID in (
#{item}
)
AND FIN_PRODUCT.TRADE_MARKET in
#{item}
AND (ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in
null) or ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in (
#{item}
)

SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ TABLE01.BRANCH branch,/*分支序号*/ NVL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt,/*可质押券面总额*/ NVL(TABLE02.AMOUNT,0) * 100 posStrdPrinAmt,/*持仓券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ NVL(fscr.SCALE, 1)*100 scale, /*折算比例*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId/*市场代码*/ FROM ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP LEFT JOIN PTL_PORTFOLIO_AUTHORITY on TEMP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE 1=1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，05融入，06融出,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 /*以上统计实际持仓*/ ON TABLE01.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND TABLE01.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID AND TABLE01.FINPROD_ID = TABLE02.FINPROD_ID AND TABLE01.BRANCH = TABLE02.BRANCH INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{plateDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = (CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO/*以上获取债券小于等于平台日的最新估值行情*/ ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID LEFT JOIN FIN_STDSEC_CONVERSE_RADIO fscr ON fscr.FINPROD_ID = TABLE01.FINPROD_ID AND fscr.BRANCH = TABLE01.BRANCH AND fscr.VDATE <= TO_DATE(#{plateDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT * FROM FIN_STDSEC_CONVERSE_RADIO fscrInner WHERE fscrInner.FINPROD_ID = fscr.FINPROD_ID AND fscrInner.BRANCH = fscr.BRANCH AND fscrInner.VDATE <= TO_DATE(#{plateDate}, 'yyyy-MM-dd') AND fscrInner.VDATE > fscr.VDATE ) WHERE 1=1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND (TABLE01.PORTFOLIO_ID in
null) or TABLE01.PORTFOLIO_ID in (
#{item}
)
AND FIN_PRODUCT.TRADE_MARKET in
#{item}
AND (TABLE01.SEC_ACCT_ID in
null) or TABLE01.SEC_ACCT_ID in (
#{item}
)

SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ TABLE01.BRANCH branch,/*分支序号*/ NVL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt,/*可质押券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ ETR_ENTRUST_PLEDGE.SCALE scale /*折算比例*/
FROM ETR_ENTRUST_PLEDGE LEFT JOIN PTL_PORTFOLIO_AUTHORITY on ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID INNER JOIN ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
WHERE 1=1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND (TABLE01.PORTFOLIO_ID in
null) or TABLE01.PORTFOLIO_ID in (
#{item}
)
AND FIN_PRODUCT.TRADE_MARKET in
#{item}
AND (TABLE01.SEC_ACCT_ID in
null) or TABLE01.SEC_ACCT_ID in (
#{item}
)

SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finprodId,/*金融产品Id*/
NVL(TABLE01.AMOUNT,0) * 100 avaPledgePrin,/*可质押券面总额*/ NVL(TABLE01.AMOUNT,0) * 100 pledgePrin,/*需要质押券面总额*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ MST_BOND_VALUATION_INFO.NETPRICE firstNetPrice,/*净价*/ NVL(MST_BOND_VALUATION_INFO.LAST_PERIOD,0) lastPeriod,/*剩余期限*/ ETR_ENTRUST_PLEDGE.SCALE pledgeRatio, /*折算比例*/ FIN_PRODUCT_TYPE.TYPE_6 windTypeOne,/*资产一级类型*/ FIN_PRODUCT_TYPE.TYPE_7 windTypeTwo,/*资产二级类型*/ decode(ETR_SEC_PRIORITY.YES_OR_NO,'Y', nvl(ETR_SEC_PRIORITY_DETAIL.pledge_pri,'03'),'03') pledgePri,/*质押优先级，未启用或未设置则为 03中*/ NVL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) bondAbbrName,/*金融产品名称*/ FIN_PRODUCT.REGIST_ORG repRegistOrg, FIN_PRODUCT.FINPROD_MARKET_ID bondCode/*市场代码*/
FROM ETR_ENTRUST_PLEDGE LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{vdate},'yyyy-MM-dd')/*组合持仓.日期 = 基准日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{vdate},'yyyy-MM-dd')/*组合持仓.日期 = 基准日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID INNER JOIN FIN_PRODUCT /*金融产品*/ ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
LEFT JOIN FIN_PRODUCT_TYPE /*金融产品分类*/ ON FIN_PRODUCT_TYPE.FINPROD_ID = ETR_ENTRUST_PLEDGE.FINPROD_ID LEFT JOIN ETR_SEC_PRIORITY_DETAIL /*质押优先级明细*/ ON FIN_PRODUCT_TYPE.type_6 = ETR_SEC_PRIORITY_DETAIL.windtypeone AND ( ETR_SEC_PRIORITY_DETAIL.windtypetwo IS NULL OR FIN_PRODUCT_TYPE.type_7 = ETR_SEC_PRIORITY_DETAIL.windtypetwo ) LEFT JOIN ETR_SEC_PRIORITY ON ETR_SEC_PRIORITY_DETAIL.CONFIG_ID = ETR_SEC_PRIORITY.CONFIG_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{vdate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = (CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID /*以上获取债券小于等于平台日的最新估值行情*/ WHERE 1=1 /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}

select tb.id hidCode, tb.id code, tb.text name, tb.text shortName from( SELECT DISTINCT A.ACCT_NO id, B.SEC_ACCT_NAME text FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
UNION ALL SELECT FINPROD_ID id , FINPROD_NAME text FROM FIN_PRODUCT
and ( FINPROD_MARKET_ID like concat(concat('%',#{search}),'%') or FINPROD_NAME like concat(concat('%',#{search}),'%') )
AND FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
)tb
